-- Gallery photos managed via admin CMS
create table public.gallery_photos (
  id          uuid primary key default gen_random_uuid(),
  url         text not null,
  caption     text,
  sort_order  int not null default 0,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now()
);

comment on table public.gallery_photos is
  'Images shown on the public /gallery page. URL may be a Supabase signed URL or a gateway /storage/v1/object/public/ URL pointing to R2.';

-- Public read; only admin writes
alter table public.gallery_photos enable row level security;

create policy "gallery: public read active"
  on public.gallery_photos for select
  using (is_active = true);

create policy "gallery: admin all"
  on public.gallery_photos for all
  using ( (select role from public.profiles where id = (select auth.uid())) = 'admin' )
  with check ( (select role from public.profiles where id = (select auth.uid())) = 'admin' );

